import {choose,chooseExcept,percent,loadState,spendDraw,rewardShare,STORAGE_KEY} from './engine.e631335941ad.js';
const $=id=>document.getElementById(id);let categories=[],sources=[],current=null,currentRound=0,busy=false,storage,state;
try{storage=window.localStorage;}catch{}state=loadState(storage);
const groupNames={Bacteria:'세균',Archaea:'고세균',Fungi:'균류',Protists:'원생생물',Animals:'동물',Plants:'식물'};
let toastTimer;function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400);}
function refresh(){if(storage)state=loadState(storage);}
function persist(){try{storage?.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storage=null;toast('브라우저 저장이 차단되어 이 탭에서만 횟수가 유지돼요.');}}
function updateCredits(){const previous=categories.find(c=>c.id===state.lastId);$('draw').disabled=!categories.length||busy;$('draw').textContent=previous?'내 생물등록증 다시 보기 ↗':'나의 다음 생 확인하기 ↗';$('home-credit').textContent=state.started?`다시하기 ${state.remaining}회 · 공유하면 +2회`:'첫 환생 무료 · 다시하기 1회';$('retry').disabled=state.remaining===0||busy;$('retry-exclude').disabled=state.remaining===0||busy||!current;$('retry').textContent=state.remaining?`다시 환생하기 · ${state.remaining}회 남음 ↻`:'다시하기를 모두 사용했어요';$('credit-status').textContent=`다시하기 ${state.remaining}회 · 공유하면 +2회`;$('share-rule').textContent=state.rewardedRound===currentRound?'이번 등록증의 공유 보너스 지급 완료':'등록증마다 보너스 1회 · 공유 창 열기·링크 복사 기준';}
function screen(view){for(const id of ['home','loading','result'])$(id).hidden=id!==view;}
function address(c){if(/해저/.test(c.name))return '지구별 깊은바다동 어딘가';if(/해양|바다|해양|남극크릴/.test(c.name)||c.id.startsWith('bio-24-'))return '지구별 푸른바다동 어딘가';if(/지하/.test(c.name))return '지구별 땅속깊은동 어딘가';if(/토양/.test(c.name))return '지구별 흙한줌동 어딘가';if(c.group==='Plants')return '지구별 초록동 어딘가';if(c.id==='bio-20')return '지구별 오늘여기동 어딘가';return '지구별 살아숨쉬는동 어딘가';}
function motto(c){if(c.id==='bio-20')return '이 귀한 확률을 뚫고, 다시 인간으로.';if(c.name==='카피바라')return '이번 생은 조금 느긋해도 괜찮아요.';if(c.group==='Plants')return '햇빛을 모으며, 천천히 자라는 다음 장.';if(c.group==='Bacteria'||c.group==='Archaea')return '존재감은 크기순이 아니니까.';if(c.group==='Fungi')return '보이지 않는 곳에서도, 삶은 이어집니다.';if(c.group==='Protists')return '작은 세상에도 커다란 이야기가 있어요.';return '새로운 몸으로 시작하는, 당신의 다음 장.';}
function shareURL(c){return new URL(`r/${c.id}/?card=1`,document.baseURI).href;}
function viewResult(c,{navigate=true,round=state.round}={}){current=c;currentRound=round;$('result-name').textContent=c.name;$('result-line').textContent=motto(c);$('card-name').textContent=c.name;$('card-name').classList.toggle('long-name',c.name.length>9);$('card-latin').textContent=c.scientificName||c.group.toUpperCase();$('card-group').textContent=c.rank==='species'?`${groupNames[c.group]} · 종 단위 결과`:`${groupNames[c.group]} · 집단 단위 결과`;$('card-address').textContent=address(c);$('card-probability').textContent=percent(c.probability)+'%';$('result-image').src=c.image;$('result-image').alt=c.name+(c.imageRole==='species'?'':' 집단의 대표 이미지');const i=categories.indexOf(c)+1;$('specimen-id').textContent=`SPECIMEN ${String(i).padStart(3,'0')}`;$('card-number').textContent=`BIO · 2026 · ${String(i).padStart(3,'0')}`;
const s=sources.find(s=>s.categoryId===c.id);$('image-caption').textContent=s?.imageRole==='conceptual-illustration'?'AI 생성 개념 삽화 · 특정 종의 실물 사진이 아닙니다.':c.imageRole==='species'?'해당 종 이미지 · 가상 생물등록증':`집단의 대표 이미지${s?.depictedTaxon?' · '+s.depictedTaxon:''} · 종별 확률 아님`;
$('image-credit').replaceChildren();if(s){const text=document.createElement('span');text.textContent=`이미지: ${s.artist||s.source} · ${s.license} · 크롭·변환 `;$('image-credit').append(text);if(s.sourceUrl){const a=document.createElement('a');a.href=s.sourceUrl;a.target='_blank';a.rel='noopener';a.textContent='원본 ↗';$('image-credit').append(a);}if(s.licenseUrl){const a=document.createElement('a');a.href=s.licenseUrl;a.target='_blank';a.rel='noopener';a.textContent=' · 라이선스 ↗';$('image-credit').append(a);}}
updateCredits();screen('result');document.title=`나의 다음 생은 ${c.name} · 생물등록증`;if(navigate)history.pushState({view:'result',id:c.id,round},'',shareURL(c));window.scrollTo({top:0,behavior:'smooth'});}
async function draw(retry=false,excludeCurrent=false){if(busy||!categories.length)return;refresh();if(!retry&&state.started&&state.lastId){const previous=categories.find(c=>c.id===state.lastId);if(previous){viewResult(previous);return;}}if(!spendDraw(state)){toast('등록증을 공유하면 다시하기 2회가 추가돼요.');return;}const excludedId=excludeCurrent?current?.id:null;const c=excludedId?chooseExcept(categories,excludedId):choose(categories);state.lastId=c.id;persist();busy=true;updateCredits();screen('loading');window.scrollTo({top:0,behavior:'smooth'});let i=0;const timer=setInterval(()=>{$('loading-name').textContent=categories[(i++*7)%categories.length].name+'의 모습으로 새로운 하루를 시작할까?';},140);await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?120:1900));clearInterval(timer);busy=false;viewResult(c);}
$('draw').onclick=()=>draw();$('retry').onclick=()=>draw(true);$('retry-exclude').onclick=()=>draw(true,true);$('reload').onclick=()=>location.reload();
function home({navigate=true}={}){current=null;screen('home');refresh();updateCredits();document.title='다시 태어나면, 어떤 생물? · 다음 생 연구소';if(navigate)history.pushState({view:'home'},'',new URL('./',document.baseURI));window.scrollTo({top:0,behavior:'smooth'});}
$('back-home').onclick=()=>home();document.querySelectorAll('.brand').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();home();}));
function grantShare(round,id){refresh();if(state.round!==round||state.lastId!==id){toast('최근 발급한 등록증에서 보너스를 받아주세요.');return;}if(rewardShare(state)){persist();updateCredits();toast('공유 보너스! 다시하기 2회가 추가됐어요.');}else toast('이번 등록증의 공유 보너스는 이미 받았어요.');}
async function copy(){if(!current)return;const round=currentRound,id=current.id,url=shareURL(current);let copied=false;try{await navigator.clipboard.writeText(url);copied=true;}catch{const input=document.createElement('textarea');input.value=url;input.style.position='fixed';input.style.top='0';document.body.append(input);input.select();copied=document.execCommand('copy');input.remove();}if(copied)grantShare(round,id);else toast('복사가 차단됐어요. 주소창의 링크를 복사해 주세요.');}
$('copy').onclick=copy;$('share').onclick=async()=>{if(!current)return;const round=currentRound,id=current.id;const data={title:`나의 다음 생은 ${current.name}`,text:`내 다음 생은 ${current.name}! 확률 ${percent(current.probability)}%. 너는 어떤 생물로 태어날까?`,url:shareURL(current)};if(navigator.share){try{await navigator.share(data);grantShare(round,id);}catch(e){if(e.name!=='AbortError')await copy();}}else await copy();};
function social(network){if(!current)return;const url=encodeURIComponent(shareURL(current)),text=encodeURIComponent(`내 다음 생은 ${current.name}! ${percent(current.probability)}%의 확률로 만난 생명. 너는 어떤 생물일까?`);const target=network==='x'?`https://x.com/intent/tweet?text=${text}&url=${url}`:`https://www.facebook.com/sharer/sharer.php?u=${url}`;const popup=window.open(target,'_blank','width=640,height=650');if(popup){popup.opener=null;grantShare(currentRound,current.id);}else toast('공유 창이 차단됐어요. 링크 복사를 이용해 주세요.');}
$('share-x').onclick=()=>social('x');$('share-facebook').onclick=()=>social('facebook');$('save').onclick=()=>{if(!current)return;const a=document.createElement('a');a.href=new URL(`og/${current.id}.jpg`,document.baseURI);a.download=`next-life-${current.id}.jpg`;document.body.append(a);a.click();a.remove();toast('등록증 JPG 저장을 시작했어요.');};
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>$(b.dataset.open).showModal());document.querySelectorAll('dialog').forEach(d=>{d.querySelectorAll('.close,.dialog-close').forEach(b=>b.onclick=()=>d.close());d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});});
addEventListener('popstate',e=>{const c=e.state?.view==='result'?categories.find(c=>c.id===e.state.id):null;if(c)viewResult(c,{navigate:false,round:e.state.round});else home({navigate:false});});addEventListener('storage',e=>{if(e.key===STORAGE_KEY){refresh();updateCredits();}});
async function init(){screen('home');document.title='다시 태어나면, 어떤 생물? · 다음 생 연구소';history.replaceState({view:'home'},'',location.href);try{const responses=await Promise.all(['categories.json','image-sources.json'].map(p=>fetch(new URL(p,document.baseURI))));if(responses.some(r=>!r.ok))throw Error('Data unavailable');[categories,sources]=await Promise.all(responses.map(r=>r.json()));if(categories.length!==72)throw Error('Invalid category count');const human=categories.find(c=>c.id==='bio-20');$('human-chance').textContent='약 '+percent(human.probability)+'%';for(const id of ['land-mammal-12','bio-13-1','bio-24-5','bio-09','land-mammal-22','bio-26']){const c=categories.find(c=>c.id===id),item=document.createElement('article');item.className='sample';const img=document.createElement('img');img.src=c.image;img.alt=c.name;img.width=300;img.height=300;img.loading='lazy';const box=document.createElement('div'),h=document.createElement('h3'),small=document.createElement('small');h.textContent=c.name;small.textContent=groupNames[c.group]+' · NEXT LIFE';box.append(h,small);item.append(img,box);$('sample-strip').append(item);}updateCredits();}catch{$('draw').disabled=true;$('draw').textContent='정보를 불러오지 못했어요';$('load-error').hidden=false;}}
init();
